(x, y, t) => {
  const cx = 240, cy = 120;
  const w1 = Math.sin(x*0.018+t*0.25)*18+Math.cos(y*0.013-t*0.18)*12;
  const w2 = Math.cos(x*0.022-t*0.3)*10+Math.sin(y*0.02+t*0.22)*14;
  const w3 = Math.sin((x+y)*0.01+t*0.15)*8;
  const sx = x+w1+w3, sy = y+w2-w3;
  const src = [
    [160+Math.sin(t*0.5)*110, 80+Math.cos(t*0.35)*60, 0.075, 2.1, 1.0],
    [320+Math.cos(t*0.45)*100, 160+Math.sin(t*0.6)*55, 0.09, 1.8, 0.9],
    [240+Math.sin(t*0.28+2)*150, 120+Math.cos(t*0.42+1)*100, 0.055, 2.5, 1.1],
    [120+Math.cos(t*0.7+1)*90, 180+Math.sin(t*0.55+3)*70, 0.11, 1.4, 0.85],
    [360+Math.sin(t*0.38+4)*100, 60+Math.cos(t*0.8+2)*80, 0.065, 2.8, 1.05],
    [240+Math.cos(t*0.32+5)*130, 200+Math.sin(t*0.5)*90, 0.085, 2.0, 0.95],
    [80+Math.sin(t*0.6+3)*70, 40+Math.cos(t*0.45+1)*50, 0.1, 1.6, 1.15],
    [400+Math.cos(t*0.55+2)*60, 200+Math.sin(t*0.4+4)*65, 0.07, 2.3, 0.9]
  ];
  let aS=0, iS=0, wA=0;
  for(const[sX,sY,f,sp,w]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp)*w;
    iS+=Math.sin(d*f*0.65+t*sp*0.55+1.7)*w;
    wA+=Math.sin(d*f*1.3-t*sp*0.8+2.5)*w*0.3;
  }
  const n=8;
  const act=aS/n, inh=iS/n, warp=wA/n;
  const bg1=(Math.sin(sx*0.035+sy*0.022+t*0.7)+Math.sin(sx*0.028-sy*0.035+t*0.95))/2;
  const bg2=Math.sin((sx+sy)*0.1+t*2.2)*0.15+Math.sin((sx-sy)*0.085-t*1.8)*0.15;
  const bg3=Math.sin(sx*0.06+t*1.3)*Math.cos(sy*0.055-t*0.9)*0.2;
  const bg=bg1+bg2+bg3;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2);
  const ang=Math.atan2(sy-cy,sx-cx);
  const sp1=Math.sin(dist*0.045-ang*3.5-t*1.3)*0.3;
  const sp2=Math.sin(dist*0.035+ang*4.5-t*1.0)*0.25;
  const sp3=Math.sin(dist*0.07-ang*2-t*2.5)*0.15;
  const spiral=sp1+sp2+sp3;
  const diffusion=act-inh*0.65+bg*0.28+spiral+warp*0.4;
  const rd1=Math.tanh(diffusion*2.0);
  const rd2=Math.tanh((diffusion*1.5+Math.sin(sx*0.08+sy*0.06+t*0.8))*1.8);
  const blend=rd1*0.6+rd2*0.4;
  const cell=Math.tanh((Math.sin(sx*0.14)*Math.sin(sy*0.14)+Math.sin((sx+sy)*0.09+t)*0.4)*1.3)*0.25;
  const micro=Math.sin(sx*0.25+t*0.5)*Math.sin(sy*0.22-t*0.4)*0.08;
  const combined=blend*0.7+cell*0.2+micro;
  const edge=1.0+Math.abs(blend)>0.65?0.18:0;
  const edgeBoost=1.0+Math.max(0,Math.abs(blend)-0.6)*0.4;
  const v=combined*0.5+0.5;
  const pal=[
    [5,12,52],[12,45,95],[18,95,120],[25,150,135],
    [60,185,130],[180,195,70],[215,160,55],[210,110,60],
    [185,65,55],[120,30,55],[60,15,48],[5,12,52]
  ];
  const idx=v*(pal.length-1);
  const i=Math.min(idx|0,pal.length-2);
  const f=idx-i;
  const smooth=f*f*(3-2*f);
  const r0=pal[i][0]+(pal[i+1][0]-pal[i][0])*smooth;
  const g0=pal[i][1]+(pal[i+1][1]-pal[i][1])*smooth;
  const b0=pal[i][2]+(pal[i+1][2]-pal[i][2])*smooth;
  const lum=0.82+Math.sin(blend*Math.PI*1.2)*0.18;
  const shimmer=Math.sin(t*3+sx*0.1+sy*0.08)*0.03+1;
  return[
    Math.min(255,(r0*lum*edgeBoost*shimmer)|0),
    Math.min(255,(g0*lum*edgeBoost*shimmer)|0),
    Math.min(255,(b0*lum*edgeBoost*shimmer)|0)
  ];
}
